// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(address actor) public {
        // Admissible domain: any address that was never granted PROPOSER_ROLE
        // (constructor granted it to nobody; only TIMELOCK_ADMIN_ROLE was granted
        // to the deployer and the contract itself).
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));

        // General rule: an account that was never granted PROPOSER_ROLE is not
        // a member, so hasRole must return false for it.
        assertTrue(!c.hasRole(c.PROPOSER_ROLE(), actor));
    }
}
